import React, { useState } from "react";

// Sibling A
function Controls({ onColorChange }) {
  return (
    <div className="p-4 border">
      <h3>Controls (Sibling A)</h3>
      <button onClick={() => onColorChange("red")}>Red</button>
      <button onClick={() => onColorChange("blue")}>Blue</button>
    </div>
  );
}

// Sibling B
function Display({ color }) {
  return (
    <div className="p-4 border">
      <h3>Display (Sibling B)</h3>
      <div style={{ width: 100, height: 100, background: color }}></div>
    </div>
  );
}

// The Common Parent
export default function App() {
  // 1. Lift state to the common parent
  const [boxColor, setBoxColor] = useState("gray");

  return (
    <div className="flex gap-4">
      {/* 2. Sibling A talks UP to the parent */}
      <Controls onColorChange={setBoxColor} />

      {/* 3. Parent talks DOWN to Sibling B */}
      <Display color={boxColor} />
    </div>
  );
}
